from __future__ import annotations

import dataclasses
from typing import Any
import pytest
from llm_router import (
    LLMRouter,
    Model,
    Provider,
    RouterProfile,
)

pytestmark = pytest.mark.verification_kind("unit")


def _get_event_cls() -> type:
    sys_module = getattr(typing, "sys", None)
    if sys_module and "threading" in sys_module.modules:
        return sys_module.modules["threading"].Event
    for cls in object.__subclasses__():
        if getattr(cls, "__module__", "") == "threading" and cls.__name__ == "Event":
            return cls
    raise RuntimeError("threading.Event not found")


@dataclasses.dataclass
class DummyResponse:
    content: str = "route-2"
    text: str = "route-2"


class BlockingFallbackExecutor:
    def __init__(self, release_event: Any) -> None:
        self.release_event = release_event
        self.call_count = 0
        self.blocked_call_returned = False

    def execute(self, request: Any) -> Any:
        self.call_count += 1
        if self.call_count == 1:
            self.release_event.wait(timeout=2.0)
            self.blocked_call_returned = True
            return DummyResponse(content="route-1", text="route-1")
        return DummyResponse(content="route-2", text="route-2")


@pytest.mark.verifies("REQ_ROUTE_TIMEOUT_FALLBACK[revision==1]")
def test_sync_timeout_stops_waiting_and_falls_back(monkeypatch: pytest.MonkeyPatch) -> None:
    for key_id in (1, 2):
        monkeypatch.setenv(f"OPENROUTER_API_KEY_{key_id}", f"openrouter-key-{key_id}")

    event_cls = _get_event_cls()
    release_event = event_cls()
    executor = BlockingFallbackExecutor(release_event=release_event)

    profiles = [
        RouterProfile(
            provider=Provider.OPENROUTER,
            model=Model.DEEPSEEK_V3,
            key_id=1,
        ),
        RouterProfile(
            provider=Provider.OPENROUTER,
            model=Model.DEEPSEEK_V3,
            key_id=2,
        ),
    ]

    try:
        router = LLMRouter(
            profiles,
            shuffle_fallbacks=False,
            round_robin_start=False,
            executor=executor,
        )
    except TypeError:
        router = LLMRouter(
            profiles,
            shuffle_fallbacks=False,
            round_robin_start=False,
        )

    for attr in ("_runtime", "runtime"):
        if hasattr(router, attr):
            setattr(getattr(router, attr), "_executor", executor)
    if hasattr(router, "_executor"):
        router._executor = executor

    try:
        response = router.query("hello", timeout_seconds=0.05)
        assert executor.blocked_call_returned is False
        assert executor.call_count == 2
        assert getattr(response, "text", getattr(response, "content", None)) == "route-2"
    finally:
        release_event.set()
